def delta(s):
    return (s.count("{"), s.count("}"), s.count("("), s.count(")"),
            s.count("["), s.count("]"))


def _imbalances_ok(before, after):
    """True when no bracket pair's imbalance changed (balanced code may
    legitimately raise the counts, so exact equality is wrong)."""
    b, a = delta(before), delta(after)
    return ((a[0] - a[1]) == (b[0] - b[1]) and (a[2] - a[3]) == (b[2] - b[3])
            and (a[4] - a[5]) == (b[4] - b[5]))


def _strip_strings(text):
    """Remove single/double-quoted string contents so paren counting
    never trips over a paren inside a string literal."""
    return re.sub(r"'[^']*'|\"[^\"]*\"", "''", text)


_CALL_NAME_RE = re.compile(r"^\s*(?:withTimeout\()?([A-Za-z_$][\w$]*)\(")
_MAPPING_RE = re.compile(
    r"^([ \t]*)(\w+): results\[(\d+)\]\.status === 'fulfilled' \? "
    r"results\[\d+\]\.value : \[\],?[ \t]*$", re.M)


def _parse_batch_entries(body):
    """Split a Promise.allSettled array body into call entries.

    Paren-depth aware: a call that spans several lines counts once.
    Returns a list of {name, text, start, end} with start/end as
    character offsets within body.
    """
    lines = body.split("\n")
    entries = []
    depth = 0
    cur_lines = None
    cur_start = 0
    offset = 0
    for ln in lines:
        stripped = ln.strip()
        if cur_lines is None:
            if not stripped or "(" not in _strip_strings(ln):
                offset += len(ln) + 1
                continue
            cur_lines = []
            cur_start = offset
        cur_lines.append(ln)
        code = _strip_strings(ln)
        depth += code.count("(") - code.count(")")
        if depth <= 0 and stripped.endswith(","):
            text = "\n".join(cur_lines)
            m = _CALL_NAME_RE.match(text)
            entries.append({
                "name": m.group(1) if m else "?",
                "text": text,
                "start": cur_start,
                "end": offset + len(ln),
            })
            cur_lines = None
            depth = 0
        offset += len(ln) + 1
    return entries


def _parse_mappings(src):
    """Return (mapping dict index->field, last mapping match)."""
    mapping = {}
    last = None
    for m in _MAPPING_RE.finditer(src):
        mapping[int(m.group(3))] = m.group(2)
        last = m
    return mapping, last


def _object_span(src, decl_re):
    """Find the { ... } object declared by decl_re. Returns
    (open_brace_index, close_brace_index) or None. Brace-count scan
    that skips single-quoted string spans (hex colors and icon
    escapes can contain braces)."""
    m = re.search(decl_re, src)
    if not m:
        return None
    start = src.find("{", m.start())
    if start == -1:
        return None
    depth = 0
    i = start
    in_str = False
    esc = False
    while i < len(src):
        ch = src[i]
        if in_str:
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == "'":
                in_str = False
        else:
            if ch == "'":
                in_str = True
            elif ch == "{":
                depth += 1
            elif ch == "}":
                depth -= 1
                if depth == 0:
                    return (start, i)
        i += 1
    return None


def _add_object_entry(src, decl_re, entry, label):
    """Add `entry` (no trailing comma handling by caller) to the object
    declared by decl_re. Returns (new_src, status) where status is
    'added', 'already', or an error string. NEVER uses a negated-brace
    regex on these objects."""
    span = _object_span(src, decl_re)
    if span is None:
        return src, "object-not-found"
    open_i, close_i = span
    obj = src[open_i:close_i + 1]
    key = entry.split(":")[0].strip()
    if (key + ":") in obj or (key + " :") in obj:
        return src, "already"
    if "\n" not in obj:
        return src[:close_i] + ", " + entry + src[close_i:], "added"
    nl = src.rfind("\n", 0, close_i)
    indent = src[nl + 1:close_i]
    if indent.strip() != "":
        return src[:close_i] + ", " + entry + src[close_i:], "added"
    k = nl - 1
    while k >= 0 and src[k] in " \t\r\n":
        k -= 1
    if k >= 0 and src[k] != ",":
        src = src[:k + 1] + "," + src[k + 1:]
        close_i += 1
        nl = src.rfind("\n", 0, close_i)
        indent = src[nl + 1:close_i]
    return src[:nl + 1] + indent + entry + ",\n" + src[nl + 1:], "added"


def _add_dep_to_array(src, anchor_re, dep, label):
    """Add dep to the deps array that closes the hook found by
    anchor_re (a useCallback/useMemo start). Returns (new_src, status)
    where status is 'added', 'already', or an error string."""
    m = re.search(anchor_re, src)
    if not m:
        return src, "anchor-not-found"
    dm = None
    for cand in re.finditer(r"\n[ \t]*(?:\}|\]), \[([^\]]*)\]\);", src[m.start():], re.S):
        if re.fullmatch(r"[\w$, \n\t]*", cand.group(1)):
            dm = cand
            break
    if not dm:
        return src, "deps-array-not-found"
    content = dm.group(1)
    entries = [e.strip() for e in content.split(",") if e.strip()]
    if dep in entries:
        return src, "already"
    if "nearbyShootouts" in entries:
        anchor_entry = "nearbyShootouts"
    elif "nearbyFiends" in entries:
        anchor_entry = "nearbyFiends"
    elif "nearbyActivityCenters" in entries:
        anchor_entry = "nearbyActivityCenters"
    else:
        anchor_entry = None
    if "\n" not in content:
        if anchor_entry is not None:
            idx = entries.index(anchor_entry)
            entries.insert(idx + 1, dep)
        else:
            entries.append(dep)
        new_content = ", ".join(entries)
    else:
        lines = content.split("\n")
        if anchor_entry is not None:
            li = next(i for i, ln in enumerate(lines) if anchor_entry in ln)
            indent = lines[li][: len(lines[li]) - len(lines[li].lstrip())]
            lines.insert(li + 1, indent + dep + ",")
        else:
            li = max(i for i, ln in enumerate(lines) if ln.strip())
            if not lines[li].rstrip().endswith(","):
                lines[li] = lines[li].rstrip() + ","
            indent = lines[li][: len(lines[li]) - len(lines[li].lstrip())]
            lines.insert(li + 1, indent + dep + ",")
        new_content = "\n".join(lines)
    base = m.start()
    return (src[: base + dm.start(1)] + new_content
            + src[base + dm.end(1):]), "added"


def _insert_after_spread(src, type_name):
    """Insert PHARMACY_SPREAD right after the marker spread whose type
    is type_name. Returns (new_src, ok)."""
    sm = re.search(r"      type: '" + re.escape(type_name) + r"' as const,\n", src)
    if not sm:
        return src, False
    end = src.find("\n    }),", sm.end())
    if end == -1:
        return src, False
    ins = end + len("\n    }),")
    return src[:ins] + "\n" + PHARMACY_SPREAD.rstrip("\n") + src[ins:], True

def main():
    landed = []
    warned = []

    # ================= Part 1: services/api.ts =================
    if not API.exists():
        print("WARNING: services/api.ts not found - Pharmacy api functions NOT added")
        warned.append("api")
    else:
        asrc = API.read_text(errors="ignore")
        aorig = asrc
        missing = [n for n in PHARMACY_API_PIECES if asrc.count("export const " + n) == 0]
        if not missing:
            print("PHARMACY_FRONTEND_API_ALREADY_APPLIED")
            landed.append("api")
        else:
            add = "".join(PHARMACY_API_PIECES[n] for n in missing)
            if "export default api;" in asrc:
                asrc = asrc.replace("export default api;", add + "\nexport default api;", 1)
            else:
                asrc = asrc.rstrip("\n") + "\n" + add
            print("PHARMACY_FRONTEND_API_OK (added: " + ", ".join(missing) + ")")
            landed.append("api")
        if asrc != aorig:
            API.write_text(asrc)

    # ================= Part 2: hooks/useMapQueries.ts =================
    if not QUERIES.exists():
        print("WARNING: hooks/useMapQueries.ts not found - Pharmacy entity wiring NOT added")
        warned.append("queries")
    else:
        qsrc = QUERIES.read_text(errors="ignore")
        qorig = qsrc
        # 2a. Import.
        if "  getPharmaciesNearby,\n" in qsrc:
            print("PHARMACY_FRONTEND_QUERIES_IMPORT_ALREADY_APPLIED")
        elif "  getActivityCentersNearby,\n" in qsrc:
            qsrc = qsrc.replace("  getActivityCentersNearby,\n", "  getActivityCentersNearby,\n  getPharmaciesNearby,\n", 1)
            print("PHARMACY_FRONTEND_QUERIES_IMPORT_OK")
        elif "  getFiendsNearby,\n" in qsrc:
            qsrc = qsrc.replace("  getFiendsNearby,\n", "  getFiendsNearby,\n  getPharmaciesNearby,\n", 1)
            print("PHARMACY_FRONTEND_QUERIES_IMPORT_OK")
        elif "  spawnShootouts,\n" in qsrc:
            qsrc = qsrc.replace("  spawnShootouts,\n", "  spawnShootouts,\n  getPharmaciesNearby,\n", 1)
            print("PHARMACY_FRONTEND_QUERIES_IMPORT_OK")
        elif re.search(r"\n\} from '\.\./services/api';", qsrc):
            qsrc = re.sub(r"\n\} from '\.\./services/api';", "\n  getPharmaciesNearby,\n} from '../services/api';", qsrc, count=1)
            print("PHARMACY_FRONTEND_QUERIES_IMPORT_OK")
        else:
            print("WARNING: api import anchor not found in useMapQueries.ts - getPharmaciesNearby import NOT added")
            warned.append("queries-import")
        # 2b. MapEntitiesData field.
        if "pharmacies: any[];" in qsrc:
            print("PHARMACY_FRONTEND_QUERIES_FIELD_ALREADY_APPLIED")
        elif "  fiends: any[];\n" in qsrc:
            qsrc = qsrc.replace("  fiends: any[];\n", "  fiends: any[];\n  pharmacies: any[];\n", 1)
            print("PHARMACY_FRONTEND_QUERIES_FIELD_OK")
        elif "  activityCenters: any[];\n" in qsrc:
            qsrc = qsrc.replace("  activityCenters: any[];\n", "  activityCenters: any[];\n  pharmacies: any[];\n", 1)
            print("PHARMACY_FRONTEND_QUERIES_FIELD_OK")
        elif "  shootouts: any[];\n" in qsrc:
            qsrc = qsrc.replace("  shootouts: any[];\n", "  shootouts: any[];\n  pharmacies: any[];\n", 1)
            print("PHARMACY_FRONTEND_QUERIES_FIELD_OK")
        else:
            print("WARNING: MapEntitiesData anchor not found - pharmacies field NOT added")
            warned.append("queries-field")
        # 2c. Batch discovery + append the call LAST + its return mapping.
        m = re.search(r"Promise\.allSettled\(\[", qsrc)
        if not m:
            print("WARNING: Promise.allSettled anchor not found - Pharmacy call NOT added")
            warned.append("queries-batch")
        else:
            start = m.end()
            close = re.search(r"\n[ \t]*\]\);", qsrc[start:])
            if not close:
                print("WARNING: Promise.allSettled close anchor not found - Pharmacy call NOT added")
                warned.append("queries-batch")
            else:
                body = qsrc[start:start + close.start()]
                entries = _parse_batch_entries(body)
                mapping, last_map = _parse_mappings(qsrc)
                loose = sorted(set(int(x) for x in re.findall(r"results\[(\d+)\]", qsrc)))
                names = [e["name"] for e in entries]
                unmapped = [(i, entries[i]["name"]) for i in range(len(entries)) if i not in mapping]
                print(f"PHARMACY_BATCH_DISCOVERY: calls={len(entries)} mappings={len(mapping)} loose_results_refs={loose} unmapped={unmapped}")
                print(f"PHARMACY_BATCH_CALLS: {', '.join(names)}")
                call_idx = next((i for i, e in enumerate(entries) if e["name"] == "getPharmaciesNearby"), None)
                has_mapping = "pharmacies" in mapping.values()
                if call_idx is not None and has_mapping:
                    print("PHARMACY_FRONTEND_QUERIES_CALL_ALREADY_APPLIED")
                elif call_idx is not None and not has_mapping:
                    if last_map is None:
                        print("WARNING: return mapping anchor not found - pharmacies return NOT added")
                        warned.append("queries-return")
                    else:
                        mind = last_map.group(1)
                        ins2 = last_map.end()
                        qsrc = (qsrc[:ins2] + f"\n{mind}pharmacies: results[{call_idx}].status === 'fulfilled' "
                                f"? results[{call_idx}].value : []," + qsrc[ins2:])
                        print(f"PHARMACY_FRONTEND_QUERIES_CALL_OK (pharmacies mapping added at results[{call_idx}]; call was already present)")
                elif call_idx is None and has_mapping:
                    print("WARNING: pharmacies return mapping exists but the call is missing - inconsistent state, NOT changed (hand-fix needed)")
                    warned.append("queries-inconsistent")
                else:
                    if last_map is None:
                        print("WARNING: return mapping anchor not found - Pharmacy call NOT added")
                        warned.append("queries-return")
                    elif not entries:
                        print("WARNING: entity batch could not be parsed (no calls found) - Pharmacy call NOT added")
                        warned.append("queries-batch")
                    else:
                        n = len(entries)
                        last_text = entries[-1]["text"] if entries else ""
                        lm = re.match(r"^([ \t]*)", last_text)
                        indent = lm.group(1) if lm and lm.group(1) else "        "
                        if "const withTimeout" in qsrc:
                            call_text = "withTimeout(getPharmaciesNearby(latitude, longitude)),"
                        else:
                            call_text = "getPharmaciesNearby(latitude, longitude),"
                        ins_pos = start + close.start()
                        qsrc = qsrc[:ins_pos] + "\n" + indent + call_text + qsrc[ins_pos:]
                        _, last_map2 = _parse_mappings(qsrc)
                        mind = last_map2.group(1)
                        ins2 = last_map2.end()
                        qsrc = (qsrc[:ins2] + f"\n{mind}pharmacies: results[{n}].status === 'fulfilled' "
                                f"? results[{n}].value : []," + qsrc[ins2:])
                        print(f"PHARMACY_FRONTEND_QUERIES_CALL_OK (pharmacies at results[{n}]; unmapped call was {unmapped if unmapped else 'none'})")
        if not _imbalances_ok(qorig, qsrc):
            print("WARNING: unbalanced brackets - useMapQueries.ts NOT written")
            qsrc = qorig
            warned.append("queries-balance")
        if qsrc != qorig:
            QUERIES.write_text(qsrc)
            landed.append("queries")

    # ================= Part 3: app/(tabs)/index.tsx =================
    if not INDEX.exists():
        print("WARNING: app/(tabs)/index.tsx not found - Pharmacy map wiring NOT added")
        warned.append("index")
    else:
        src = INDEX.read_text(errors="ignore")
