        # 3g. mapMarkers spread + deps.
        if "type: 'pharmacy' as const," in src:
            print("PHARMACY_FRONTEND_INDEX_MARKERS_ALREADY_APPLIED")
        else:
            done = False
            for t in ("fiend", "activityCenter", "shootout"):
                src2, ok = _insert_after_spread(src, t)
