        # 4b. markerColors via brace-scan (never a negated-brace regex).
        gsrc, status = _add_object_entry(gsrc, r"var markerColors\s*=\s*\{", "pharmacy: '#009688'", "color")
        if status == "added":
            print("PHARMACY_FRONTEND_GAMEMAP_COLOR_OK")
        elif status == "already":
            print("PHARMACY_FRONTEND_GAMEMAP_COLOR_ALREADY_APPLIED")
