        # 4c. markerIcons via brace-scan, literal pill character.
        gsrc, status = _add_object_entry(gsrc, r"var markerIcons\s*=\s*\{", "pharmacy: '💊'", "icon")
        if status == "added":
            print("PHARMACY_FRONTEND_GAMEMAP_ICON_OK")
        elif status == "already":
            print("PHARMACY_FRONTEND_GAMEMAP_ICON_ALREADY_APPLIED")
